  ["9f2d1b9293e58e7e"] = { "Quale istruttore di classe stai cercando?", "." },
  ["9f3a413c248c5159"] = { "Bene, squadra. Mettetevi al lavoro per montare queste ossa.", "." },
  ["9f3b162ac51c9e90"] = { "Veniamo dal profondo! Non potrete mai fermarci!", "." },
  ["9f3eb19c9ecd42e6"] = { "Fate largo!", "." },
  ["9f40b9964bedf919"] = { "Grazie! Grazie, <sacerdote/sacerdotessa>. Ora posso affrontare quegli gnoll con il tuo potere a sostenermi!", "." },
  ["9f41a57659d58eef"] = { "Maywiki, ho perso il mio ⟦Zandalar Augur's Hauberk=Usbergo del Profeta degli Zandalari⟧ e me ne serve uno nuovo.", "." },
  ["9f4a2c4af3d3e259"] = { "Macellaio, dici? Ah, istruttore di ⟦First Aid=Primo Soccorso⟧! Fa lo stesso. Quando vedrai l'infermiera Neela appena dentro la ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, nella parte sud-est della città, capirai perché.", "." },
  ["9f4b42691a8f7c5c"] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è cominciata!", "." },
