  ["9f660fe2cecf194d"] = { "Questa non è una giostra, <pivello/pivella>. Sparisci.", "." },
  ["9f6ceb23ca655df9"] = { "ORA TOCCA A VOI, INSETTI! AVETE OSATO CERCARE IL POTERE DI RAGNAROS. ORA LO VEDRETE CON I VOSTRI OCCHI!", "." },
  ["9f7d9def7d496846"] = { "La mia famiglia vanta la più bella collezione di gioielli e oggetti d'arte fra tutti i nobili di ⟦Stormwind=Roccavento⟧!\n\nE desideriamo sempre ampliare la nostra collezione...", "." },
  ["9f840b353e502b74"] = { "Per ora abbiamo solo un piccolo punto d'appoggio su questo continente, ma gli umani non potranno respingerci per sempre. Allora la pagheranno per averci resi schiavi. Taglieremo le loro lingue bugiarde per il loro tradimento.", "." },
